}

function createEmptyUsage() {
    return {
        input: 0,
        output: 0,
        cacheRead: 0,
        cacheWrite: 0,
        totalTokens: 0,
        cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
    };
}

function appendRewriteDiagnostic(message, rewrite) {
    if (!rewrite) {
        return;
    }
    appendAssistantMessageDiagnostic(message, {
        type: "pi_messages_rewrite",
        timestamp: Date.now(),
        details: { ...rewrite },
    });
}

